"""Round-6 coverage: lookup/status tables, unused columns, thin techniques (LIKE, REGEXP, UNION, RIGHT/CROSS JOIN, purchasing and invoicing).
Written from a measured coverage gap (tables/columns/techniques with 0-3 entries), not from held-out wording. MySQL 8.0.28 syntax only.
Same format as bank_sql4: `sql` and `alt` must return identical result sets."""

def S(number, question, sql, alt, explanation, pattern, tags, techniques, cmp='set'):
    return dict(id='SQL5-%03d' % number, question=question, sql=sql, alt=alt, explanation=explanation, pattern=pattern,
                tags=tags.split('|'), techniques=techniques.split('|'), difficulty=3, cmp=cmp, mode=None, check=None, cleanup=None)

SQL5 = [
 S(1, "Show every order status name with the number of orders in that status, including statuses that have no orders (count 0).",
   "SELECT s.`Status Name`, COUNT(o.`Order ID`) FROM `orders status` s LEFT JOIN orders o ON o.`Status ID`=s.`Status ID` GROUP BY s.`Status ID`, s.`Status Name`;",
   "SELECT s.`Status Name`, (SELECT COUNT(*) FROM orders o WHERE o.`Status ID`=s.`Status ID`) FROM `orders status` s;",
   "The lookup table is the preserved side of the LEFT JOIN, so unused statuses show 0; counting o.`Order ID` (not *) avoids counting the NULL-extended row as 1. Grouping by the status key as well as its name keeps two statuses with the same name apart.",
   'left_join', 'status lookup|count per status|zero groups|left join', 'LEFT JOIN from lookup|correlated count'),
 S(2, "Count order-detail lines per line status name, listing all line statuses including those never used.",
   "SELECT s.`Status Name`, COUNT(d.ID) FROM `order details status` s LEFT JOIN `order details` d ON d.`Status ID`=s.`Status ID` GROUP BY s.`Status ID`, s.`Status Name`;",
   "SELECT s.`Status Name`, (SELECT COUNT(*) FROM `order details` d WHERE d.`Status ID`=s.`Status ID`) FROM `order details status` s;",
   "Order details have their own status table (None, Allocated, Invoiced, Shipped, On Order, No Stock), separate from order statuses. The join key is `Status ID` on both sides; lines with a NULL status match no row and are not counted.",
   'left_join', 'line status|order details status|zero groups|lookup', 'LEFT JOIN from lookup|correlated count'),
 S(3, "Show each purchase order status name with its number of purchase orders and the total number of its received detail lines; keep statuses without purchase orders.",
   "SELECT s.Status, COUNT(DISTINCT p.`Purchase Order ID`), COUNT(d.`Date Received`) FROM `purchase order status` s LEFT JOIN `purchase orders` p ON p.`Status ID`=s.`Status ID` LEFT JOIN `purchase order details` d ON d.`Purchase Order ID`=p.`Purchase Order ID` GROUP BY s.`Status ID`, s.Status;",
   "SELECT s.Status, (SELECT COUNT(*) FROM `purchase orders` p WHERE p.`Status ID`=s.`Status ID`), (SELECT COUNT(d.`Date Received`) FROM `purchase orders` p JOIN `purchase order details` d ON d.`Purchase Order ID`=p.`Purchase Order ID` WHERE p.`Status ID`=s.`Status ID`) FROM `purchase order status` s;",
   "Two levels of children (orders, then lines) multiply rows, so purchase orders are counted with COUNT(DISTINCT) while received lines use COUNT(column), which skips NULL Date Received. The alternative avoids the fan-out with independent scalar counts.",
   'multi_agg', 'purchase order status|fan out|count distinct|received lines', 'two-level LEFT JOIN with DISTINCT|independent scalar counts'),
 S(4, "List the employees who have no privilege assigned in employee privileges; show employee ID and last name.",
   "SELECT e.ID, e.`Last Name` FROM employees e WHERE NOT EXISTS (SELECT 1 FROM `employee privileges` p WHERE p.`Employee ID`=e.ID);",
   "SELECT e.ID, e.`Last Name` FROM employees e LEFT JOIN `employee privileges` p ON p.`Employee ID`=e.ID WHERE p.`Employee ID` IS NULL;",
   "Anti-join on a link table: NOT EXISTS or LEFT JOIN ... IS NULL. NOT IN would return nothing if the link column contained a NULL. Eight of the nine employees have no privilege in this dump.",
   'not_exists', 'employee privileges|anti join|no privilege|link table', 'NOT EXISTS|LEFT JOIN IS NULL'),
 S(5, "Show every employee that has a privilege together with the privilege name; show employee ID, last name and privilege name.",
   "SELECT e.ID, e.`Last Name`, p.`Privilege Name` FROM employees e JOIN `employee privileges` ep ON ep.`Employee ID`=e.ID JOIN privileges p ON p.`Privilege ID`=ep.`Privilege ID`;",
   "SELECT e.ID, e.`Last Name`, (SELECT p.`Privilege Name` FROM privileges p WHERE p.`Privilege ID`=ep.`Privilege ID`) FROM employees e JOIN `employee privileges` ep ON ep.`Employee ID`=e.ID WHERE EXISTS (SELECT 1 FROM privileges p WHERE p.`Privilege ID`=ep.`Privilege ID`);",
   "Link-table pattern: employees and privileges are many-to-many through `employee privileges`, so two joins are needed. Inner joins show only employees that have a privilege; use LEFT JOINs to keep the others with NULL. The alternative resolves the privilege name with a scalar subquery and keeps inner-join semantics with EXISTS.", 'inner_join', 'employee privileges|many to many|link table|privilege name', 'link table join|scalar lookup'),
 S(6, "Find the messages in the strings table whose text contains the word 'remove' in any letter case; show string ID and text.",
   "SELECT `String ID`, `String Data` FROM strings WHERE `String Data` LIKE '%remove%';",
   "SELECT `String ID`, `String Data` FROM (SELECT `String ID`, `String Data`, LOCATE('remove', LOWER(`String Data`)) AS position FROM strings) found WHERE position > 0;",
   "LIKE with a leading % cannot use an index, but that is fine for a 62-row lookup. Matching is case-insensitive here because the column collation is _ci; LOWER plus LOCATE is the explicit equivalent that does not depend on collation. Escape literal % or _ with a backslash.",
   'select_filter', 'like|wildcard|text search|strings table', 'LIKE wildcard|LOCATE on LOWER'),
 S(7, "List the products whose Quantity Per Unit mentions bottles; show ID, product name and the packaging text.",
   "SELECT ID, `Product Name`, `Quantity Per Unit` FROM products WHERE `Quantity Per Unit` LIKE '%bottle%';",
   "SELECT ID, `Product Name`, `Quantity Per Unit` FROM products WHERE `Quantity Per Unit` REGEXP 'bottle';",
   "LIKE '%bottle%' and REGEXP 'bottle' both do a substring search; REGEXP is more powerful (anchors, classes, alternation) but less readable for a plain word. Both are case-insensitive under the default collation.",
   'string_funcs', 'like|regexp|packaging text|products', 'LIKE substring|REGEXP substring'),
 S(8, "List the products whose Quantity Per Unit starts with digits followed by a space; show ID, name and packaging text.",
   "SELECT ID, `Product Name`, `Quantity Per Unit` FROM products WHERE `Quantity Per Unit` REGEXP '^[0-9]+ ';",
   "SELECT ID, `Product Name`, `Quantity Per Unit` FROM products WHERE LOCATE(' ', `Quantity Per Unit`) > 1 AND CAST(SUBSTRING_INDEX(`Quantity Per Unit`, ' ', 1) AS UNSIGNED) > 0 AND CAST(SUBSTRING_INDEX(`Quantity Per Unit`, ' ', 1) AS UNSIGNED) = SUBSTRING_INDEX(`Quantity Per Unit`, ' ', 1) + 0 AND SUBSTRING_INDEX(`Quantity Per Unit`, ' ', 1) = CAST(CAST(SUBSTRING_INDEX(`Quantity Per Unit`, ' ', 1) AS UNSIGNED) AS CHAR);",
   "^ anchors the match to the start, [0-9]+ means one or more digits, then a literal space. The alternative takes the first word and checks that it is non-empty, all digits, and followed by a space. Plain LIKE cannot express 'digits only', which is why REGEXP is the tool here.",
   'string_funcs', 'regexp|pattern|anchor|packaging text', 'REGEXP anchored|SUBSTRING_INDEX plus NOT REGEXP'),
 S(9, "List every distinct city where we have a customer, a supplier or an employee, each city once, using UNION.",
   "SELECT City FROM customers WHERE City IS NOT NULL UNION SELECT City FROM suppliers WHERE City IS NOT NULL UNION SELECT City FROM employees WHERE City IS NOT NULL;",
   "SELECT DISTINCT City FROM (SELECT City FROM customers UNION ALL SELECT City FROM suppliers UNION ALL SELECT City FROM employees) x WHERE City IS NOT NULL;",
   "UNION removes duplicates across all branches; UNION ALL keeps them, so the alternative needs DISTINCT. Column count and compatible types must match in every branch. NULL cities are filtered because NULL is not a place.",
   'set_ops', 'union|distinct cities|combine tables|set operation', 'UNION|UNION ALL with DISTINCT'),
 S(10, "List the cities that have both at least one customer and at least one employee without using INTERSECT; show each city once.",
   "SELECT DISTINCT c.City FROM customers c WHERE c.City IS NOT NULL AND c.City IN (SELECT e.City FROM employees e WHERE e.City IS NOT NULL);",
   "SELECT c.City FROM customers c JOIN employees e ON e.City=c.City GROUP BY c.City;",
   "INTERSECT only exists from MySQL 8.0.31, so on 8.0.28 emulate it with IN/EXISTS or a join plus GROUP BY/DISTINCT. NULLs are removed explicitly because NULL never equals NULL.",
   'set_ops', 'intersect emulation|cities|in subquery|8.0.28', 'IN subquery with DISTINCT|join with GROUP BY'),
 S(11, "List the cities that have a customer but no employee without using EXCEPT; show each city once.",
   "SELECT DISTINCT c.City FROM customers c WHERE c.City IS NOT NULL AND NOT EXISTS (SELECT 1 FROM employees e WHERE e.City=c.City);",
   "SELECT DISTINCT c.City FROM customers c LEFT JOIN employees e ON e.City=c.City WHERE c.City IS NOT NULL AND e.ID IS NULL;",
   "EXCEPT needs 8.0.31, so use NOT EXISTS or a LEFT JOIN anti-join. NOT IN would be wrong if employees.City contained a NULL, because x NOT IN (..., NULL) is never true.",
   'not_exists', 'except emulation|cities|anti join|8.0.28', 'NOT EXISTS with DISTINCT|LEFT JOIN anti join'),
 S(12, "Using a RIGHT JOIN with orders written on the left, list every shipper with its number of orders, including shippers with none.",
   "SELECT s.Company, COUNT(o.`Order ID`) FROM orders o RIGHT JOIN shippers s ON s.ID=o.`Shipper ID` GROUP BY s.ID, s.Company;",
   "SELECT s.Company, COUNT(o.`Order ID`) FROM shippers s LEFT JOIN orders o ON o.`Shipper ID`=s.ID GROUP BY s.ID, s.Company;",
   "A RIGHT JOIN keeps all rows of the table on its right; swapping the two tables turns it into the equivalent LEFT JOIN. Counting a column of the optional side (not COUNT(*)) gives 0 for shippers without orders. Orders with a NULL shipper belong to no shipper and are not shown.",
   'left_join', 'right join|shippers|preserved side|count zero', 'RIGHT JOIN|equivalent LEFT JOIN'),
 S(13, "Produce a grid of every shipper against every order status name with the number of orders for each pair, showing zero for pairs without orders.",
   "SELECT sh.Company, st.`Status Name`, COUNT(o.`Order ID`) FROM shippers sh CROSS JOIN `orders status` st LEFT JOIN orders o ON o.`Shipper ID`=sh.ID AND o.`Status ID`=st.`Status ID` GROUP BY sh.ID, sh.Company, st.`Status ID`, st.`Status Name`;",
   "SELECT sh.Company, st.`Status Name`, (SELECT COUNT(*) FROM orders o WHERE o.`Shipper ID`=sh.ID AND o.`Status ID`=st.`Status ID`) FROM shippers sh JOIN `orders status` st ON TRUE;",
   "CROSS JOIN builds every combination first (3 shippers x 4 statuses = 12 rows); the LEFT JOIN then attaches the facts, and the match conditions go in ON so unmatched pairs survive with count 0. Putting them in WHERE would silently drop the empty cells.",
   'left_join', 'cross join|matrix|all combinations|zero cells', 'CROSS JOIN then LEFT JOIN|JOIN ON TRUE with scalar counts'),
 S(14, "Count orders per Payment Type, showing orders without a payment type as 'Not recorded'; order by count descending then label.",
   "SELECT COALESCE(`Payment Type`, 'Not recorded') AS method, COUNT(*) FROM orders GROUP BY COALESCE(`Payment Type`, 'Not recorded') ORDER BY COUNT(*) DESC, method;",
   "SELECT method, COUNT(*) FROM (SELECT IF(`Payment Type` IS NULL, 'Not recorded', `Payment Type`) AS method FROM orders) x GROUP BY method ORDER BY COUNT(*) DESC, method;",
   "GROUP BY puts all NULLs in one group; COALESCE gives that group a readable label. The expression must be repeated (or wrapped in a derived table) because MySQL allows aliases in GROUP BY only as an extension. NULL means unknown, not 'unpaid'.",
   'null_handling', 'null label|payment type|coalesce|group by null', 'COALESCE in GROUP BY|derived table with IF'),
 S(15, "List customers whose Job Title contains 'Manager'; show ID, company, last name and job title.",
   "SELECT ID, Company, `Last Name`, `Job Title` FROM customers WHERE `Job Title` LIKE '%Manager%';",
   "SELECT ID, Company, `Last Name`, `Job Title` FROM customers WHERE `Job Title` REGEXP 'Manager';",
   "Substring search with LIKE or REGEXP. Both 'Purchasing Manager' and 'Accounting Manager' match; use LIKE '% Manager' to anchor at the end if only titles ending in Manager are wanted.",
   'string_funcs', 'like|job title|managers|substring', 'LIKE substring|REGEXP substring'),
 S(16, "Count the orders whose Order Date falls on a Saturday or Sunday.",
   "SELECT COUNT(*) FROM orders WHERE WEEKDAY(`Order Date`) IN (5, 6);",
   "SELECT SUM(CASE WHEN DAYNAME(`Order Date`) IN ('Saturday', 'Sunday') THEN 1 ELSE 0 END) FROM orders;",
   "WEEKDAY numbers Monday as 0 so Saturday and Sunday are 5 and 6, whereas DAYOFWEEK starts at Sunday = 1 (Sunday 1, Saturday 7). DAYNAME depends on lc_time_names (English by default). The time part of Order Date does not matter.",
   'date', 'weekend|weekday|dayname|date function', 'WEEKDAY numbers|DAYNAME names'),
 S(17, "List closed orders (status name Closed) paid by Credit Card with the customer company; show order ID, company and order date.",
   "SELECT o.`Order ID`, c.Company, o.`Order Date` FROM orders o JOIN `orders status` s ON s.`Status ID`=o.`Status ID` JOIN customers c ON c.ID=o.`Customer ID` WHERE s.`Status Name`='Closed' AND o.`Payment Type`='Credit Card';",
   "SELECT o.`Order ID`, (SELECT c.Company FROM customers c WHERE c.ID=o.`Customer ID`), o.`Order Date` FROM orders o WHERE o.`Status ID` = (SELECT `Status ID` FROM `orders status` WHERE `Status Name`='Closed') AND o.`Payment Type`='Credit Card' AND EXISTS (SELECT 1 FROM customers c WHERE c.ID=o.`Customer ID`);",
   "Filter by the status NAME through the lookup table rather than hard-coding the numeric id 3, so the query survives renumbering. The inner join drops orders whose customer is missing; the alternative keeps the same semantics with EXISTS.",
   'inner_join', 'status name|payment type|credit card|lookup join', 'lookup join|scalar status lookup'),
 S(18, "For purchase orders that have both a Submitted Date and an Approved Date, return the average number of days between them, rounded to two decimals.",
   "SELECT ROUND(AVG(DATEDIFF(`Approved Date`, `Submitted Date`)), 2) FROM `purchase orders` WHERE `Submitted Date` IS NOT NULL AND `Approved Date` IS NOT NULL;",
   "SELECT ROUND(SUM(days) / COUNT(*), 2) FROM (SELECT DATEDIFF(`Approved Date`, `Submitted Date`) AS days FROM `purchase orders` WHERE `Submitted Date` IS NOT NULL AND `Approved Date` IS NOT NULL) waits;",
   "Both dates must exist or DATEDIFF is NULL and AVG would silently skip the row anyway; filtering explicitly makes the intent visible and keeps COUNT(*) consistent in the alternative. DATEDIFF counts calendar days and ignores times.",
   'date', 'approval time|average days|purchase orders|datediff', 'AVG of DATEDIFF|SUM divided by COUNT'),
 S(19, "List approved purchase orders (status name Approved) that have no Payment Date, with the supplier company; show purchase order ID and company.",
   "SELECT p.`Purchase Order ID`, s.Company FROM `purchase orders` p JOIN `purchase order status` st ON st.`Status ID`=p.`Status ID` JOIN suppliers s ON s.ID=p.`Supplier ID` WHERE st.Status='Approved' AND p.`Payment Date` IS NULL;",
   "SELECT p.`Purchase Order ID`, (SELECT s.Company FROM suppliers s WHERE s.ID=p.`Supplier ID`) FROM `purchase orders` p WHERE p.`Status ID`=(SELECT `Status ID` FROM `purchase order status` WHERE Status='Approved') AND p.`Payment Date` IS NULL AND p.`Supplier ID` IN (SELECT ID FROM suppliers);",
   "Unpaid means Payment Date IS NULL (never = NULL). Status is read through its lookup name. In this dump no purchase order has a Payment Date, so every approved one qualifies.",
   'inner_join', 'approved|unpaid|purchase order|supplier', 'lookup and supplier joins|scalar lookups with IN'),
 S(20, "For each supplier with at least two purchase orders show the number of purchase orders and the date of the latest Creation Date.",
   "SELECT `Supplier ID`, COUNT(*), MAX(`Creation Date`) FROM `purchase orders` WHERE `Supplier ID` IS NOT NULL GROUP BY `Supplier ID` HAVING COUNT(*) >= 2;",
   "SELECT p.`Supplier ID`, (SELECT COUNT(*) FROM `purchase orders` q WHERE q.`Supplier ID`=p.`Supplier ID`), MAX(p.`Creation Date`) FROM `purchase orders` p WHERE p.`Supplier ID` IS NOT NULL AND (SELECT COUNT(*) FROM `purchase orders` q WHERE q.`Supplier ID`=p.`Supplier ID`) >= 2 GROUP BY p.`Supplier ID`;",
   "'At least two' is >= 2 in HAVING, evaluated after grouping; WHERE cannot filter on COUNT. The alternative repeats the count as a correlated subquery in WHERE. Suppliers without any purchase order are not shown.",
   'group_having', 'at least two|supplier|latest date|having count', 'GROUP BY HAVING|correlated count in WHERE'),
 S(21, "List invoices whose Invoice Date is earlier than the Order Date of their order; show invoice ID, order ID and both dates.",
   "SELECT i.`Invoice ID`, i.`Order ID`, i.`Invoice Date`, o.`Order Date` FROM invoices i JOIN orders o ON o.`Order ID`=i.`Order ID` WHERE i.`Invoice Date` < o.`Order Date`;",
   "SELECT i.`Invoice ID`, i.`Order ID`, i.`Invoice Date`, (SELECT o.`Order Date` FROM orders o WHERE o.`Order ID`=i.`Order ID`) FROM invoices i WHERE EXISTS (SELECT 1 FROM orders o WHERE o.`Order ID`=i.`Order ID` AND o.`Order Date` > i.`Invoice Date`);",
   "Compares a column of the child with a column of its parent through the join. This is a data-quality check; in this dump 22 invoices are dated one day before their order (for example invoice 2006-04-04 11:05 for an order dated 2006-04-05), so the hits are real data inconsistencies to report, not a bug in the query.",
   'inner_join', 'data quality|invoice date|order date|parent child', 'join comparison|EXISTS with scalar'),
 S(22, "List the products that were written off (inventory transaction type Waste) at least once, with the total wasted quantity; show product ID, name and quantity.",
   "SELECT p.ID, p.`Product Name`, SUM(t.Quantity) FROM products p JOIN `inventory transactions` t ON t.`Product ID`=p.ID JOIN `inventory transaction types` y ON y.ID=t.`Transaction Type` WHERE y.`Type Name`='Waste' GROUP BY p.ID, p.`Product Name`;",
   "SELECT p.ID, p.`Product Name`, (SELECT SUM(t.Quantity) FROM `inventory transactions` t WHERE t.`Product ID`=p.ID AND t.`Transaction Type`=(SELECT ID FROM `inventory transaction types` WHERE `Type Name`='Waste')) FROM products p WHERE EXISTS (SELECT 1 FROM `inventory transactions` t WHERE t.`Product ID`=p.ID AND t.`Transaction Type`=(SELECT ID FROM `inventory transaction types` WHERE `Type Name`='Waste'));",
   "Transaction type is filtered by its NAME through the lookup table. SUM over the matching rows gives the wasted quantity; the EXISTS in the alternative restricts to products that have at least one such row. EMPTY RESULT in this dump: no inventory transaction has type Waste, so the query is a pattern reference.",
   'inner_join', 'waste|inventory transactions|type name|sum', 'lookup join with SUM|scalar SUM with EXISTS'),
 S(23, "For each product category show how many products exist and how many of them have a Minimum Reorder Quantity recorded (not NULL).",
   "SELECT Category, COUNT(*), COUNT(`Minimum Reorder Quantity`) FROM products GROUP BY Category;",
   "SELECT Category, COUNT(*), SUM(CASE WHEN `Minimum Reorder Quantity` IS NULL THEN 0 ELSE 1 END) FROM products GROUP BY Category;",
   "COUNT(*) counts rows, COUNT(column) counts non-NULL values, so the difference is the number of missing values. The boolean SUM does the same and is useful when the condition is more complex than NOT NULL.",
   'null_handling', 'count column|not null|missing values|category', 'COUNT(column)|boolean SUM'),
 S(24, "List products whose Target Level is not greater than twice their Reorder Level, and products with a NULL Target Level, in one result; show ID, name and both levels.",
   "SELECT ID, `Product Name`, `Reorder Level`, `Target Level` FROM products WHERE `Target Level` <= 2 * `Reorder Level` OR `Target Level` IS NULL;",
   "SELECT ID, `Product Name`, `Reorder Level`, `Target Level` FROM products WHERE NOT EXISTS (SELECT 1 FROM products q WHERE q.ID = products.ID AND q.`Target Level` > 2 * q.`Reorder Level`);",
   "NOT (a > b) is not the same as a <= b when a NULL is involved: with NULL both are unknown and the row is dropped, which is why the IS NULL branch is spelled out. Arithmetic on the column side prevents index use.",
   'null_handling', 'target level|reorder level|null|negation', 'explicit OR IS NULL|NOT of strict comparison'),
 S(25, "For every order status name list the orders' total shipping fee, treating orders without a Shipping Fee as 0, and keep statuses with no orders.",
   "SELECT s.`Status Name`, COALESCE(SUM(o.`Shipping Fee`), 0) FROM `orders status` s LEFT JOIN orders o ON o.`Status ID`=s.`Status ID` GROUP BY s.`Status ID`, s.`Status Name`;",
   "SELECT s.`Status Name`, COALESCE((SELECT SUM(o.`Shipping Fee`) FROM orders o WHERE o.`Status ID`=s.`Status ID`), 0) FROM `orders status` s;",
   "SUM over no rows (or only NULLs) is NULL, not 0, so COALESCE converts it after aggregation; wrapping the column instead (SUM(COALESCE(x,0))) would not fix statuses without any order. Mind that COALESCE can also hide data that is really missing.",
   'null_handling', 'sum null|coalesce|status|left join', 'COALESCE around SUM|scalar SUM with COALESCE'),
 S(26, "Find customers who did not place any orders during 2006, including customers who have never placed an order; return their ID, First Name and Last Name.",
   "SELECT c.ID, c.`First Name`, c.`Last Name` FROM customers c WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.`Customer ID`=c.ID AND o.`Order Date` >= '2006-01-01' AND o.`Order Date` < '2007-01-01');",
   "SELECT c.ID, c.`First Name`, c.`Last Name` FROM customers c LEFT JOIN orders o ON o.`Customer ID`=c.ID AND o.`Order Date` >= '2006-01-01' AND o.`Order Date` < '2007-01-01' WHERE o.`Order ID` IS NULL;",
   "Interpretation: a customer qualifies when NO order of theirs falls in 2006, which automatically includes customers with no orders at all. In the LEFT JOIN form the year condition must be in ON, not WHERE: LEFT JOIN orders ... WHERE YEAR(o.`Order Date`) <> 2006 turns the outer join into an inner join and also drops customers without orders (it returns 0 rows here). A half-open date range keeps an index on Order Date usable, unlike YEAR(`Order Date`) = 2006. In this dump all 48 orders are from 2006, so the answer equals the customers who never ordered (14 rows).",
   'not_exists', 'no orders in year|customers without orders|anti join|2006', 'NOT EXISTS with date range|LEFT JOIN with period in ON'),
 S(27, "List all customers and the number of orders they placed during 2006, including customers with no orders during that year; return customer ID, First Name, Last Name and TotalOrders, sorted by TotalOrders descending.",
   "SELECT c.ID, c.`First Name`, c.`Last Name`, COUNT(o.`Order ID`) AS TotalOrders FROM customers c LEFT JOIN orders o ON o.`Customer ID`=c.ID AND o.`Order Date` >= '2006-01-01' AND o.`Order Date` < '2007-01-01' GROUP BY c.ID, c.`First Name`, c.`Last Name` ORDER BY TotalOrders DESC, c.ID;",
   "SELECT c.ID, c.`First Name`, c.`Last Name`, (SELECT COUNT(*) FROM orders o WHERE o.`Customer ID`=c.ID AND o.`Order Date` >= '2006-01-01' AND o.`Order Date` < '2007-01-01') AS TotalOrders FROM customers c ORDER BY TotalOrders DESC, c.ID;",
   "The year condition belongs in the ON clause of the LEFT JOIN: put it in WHERE (WHERE YEAR(o.`Order Date`) = 2006) and customers without a 2006 order disappear, leaving 15 of the 29 customers instead of all of them. COUNT(o.`Order ID`) counts only matched orders, so customers with none show 0; COUNT(*) would show 1 for them. The ID tie-break makes the sort deterministic because many customers share the same count.",
   'left_join', 'orders per customer in year|left join|count zero|period in on', 'LEFT JOIN with period in ON|correlated count', 'ordered'),
 S(28, "Find pairs of different products that appear together in at least 2 distinct orders. Return the two product IDs and the number of distinct orders containing both products. Display each pair only once, so (A, B) and (B, A) count as the same pair. Sort by the order count in descending order.",
   "SELECT a.`Product ID` AS product_1, b.`Product ID` AS product_2, COUNT(DISTINCT a.`Order ID`) AS order_count FROM `order details` a JOIN `order details` b ON a.`Order ID`=b.`Order ID` AND a.`Product ID` < b.`Product ID` GROUP BY a.`Product ID`, b.`Product ID` HAVING COUNT(DISTINCT a.`Order ID`) >= 2 ORDER BY order_count DESC;",
   "SELECT p1, p2, COUNT(*) FROM (SELECT DISTINCT a.`Order ID` AS oid, a.`Product ID` AS p1, b.`Product ID` AS p2 FROM `order details` a JOIN `order details` b ON a.`Order ID`=b.`Order ID` WHERE a.`Product ID` < b.`Product ID`) t GROUP BY p1, p2 HAVING COUNT(*) >= 2 ORDER BY COUNT(*) DESC;",
   "Self join of the order-line table on Order ID. a.`Product ID` < b.`Product ID` (not <>) keeps each unordered pair once and never pairs a product with itself; <> would return both (A,B) and (B,A). COUNT(DISTINCT Order ID) protects against a product appearing on several lines of one order. HAVING (not WHERE) filters the aggregated count. Pairs with equal counts come back in no fixed order because the question gives no tie-break.",
   'self_join', 'product pairs|bought together|self join|count distinct|having', 'self join with < for unordered pairs|DISTINCT subquery then count', 'set'),
 S(29, "Find the most expensive products in each category. If multiple products share the highest List Price within a category, return all of them. Display ID, Product Name, Category, and List Price. Sort by Category alphabetically, then by ID in ascending order.",
   "SELECT p.ID, p.`Product Name`, p.Category, p.`List Price` FROM products p WHERE p.`List Price` = (SELECT MAX(q.`List Price`) FROM products q WHERE q.Category = p.Category) ORDER BY p.Category, p.ID;",
   "SELECT ID, `Product Name`, Category, `List Price` FROM (SELECT *, RANK() OVER (PARTITION BY Category ORDER BY `List Price` DESC) AS rk FROM products) t WHERE rk = 1 ORDER BY Category, ID;",
   "Max per group keeping ties: compare each product with the MAX of its own category (correlated on Category). Equality keeps every tied product, unlike LIMIT 1. RANK() = 1 is the window-function equivalent and also keeps ties. Products with NULL List Price never equal MAX, so they are dropped; ID is unique, so the sort is fully deterministic.",
   'correlated', 'most expensive per category|max per group|ties|correlated subquery', 'correlated MAX subquery|RANK window', 'ordered'),
 S(30, "Find customers who placed at least 3 distinct orders containing products in the 'Beverages' category during 2006. Return customer ID, First Name, Last Name, and TotalOrders. Sort by TotalOrders in descending order.",
   "SELECT c.ID, c.`First Name`, c.`Last Name`, COUNT(DISTINCT o.`Order ID`) AS TotalOrders FROM customers c JOIN orders o ON o.`Customer ID`=c.ID JOIN `order details` d ON d.`Order ID`=o.`Order ID` JOIN products p ON p.ID=d.`Product ID` WHERE p.Category='Beverages' AND o.`Order Date` >= '2006-01-01' AND o.`Order Date` < '2007-01-01' GROUP BY c.ID, c.`First Name`, c.`Last Name` HAVING COUNT(DISTINCT o.`Order ID`) >= 3 ORDER BY TotalOrders DESC;",
   "SELECT c.ID, c.`First Name`, c.`Last Name`, (SELECT COUNT(*) FROM orders o WHERE o.`Customer ID`=c.ID AND o.`Order Date` >= '2006-01-01' AND o.`Order Date` < '2007-01-01' AND EXISTS (SELECT 1 FROM `order details` d JOIN products p ON p.ID=d.`Product ID` WHERE d.`Order ID`=o.`Order ID` AND p.Category='Beverages')) AS TotalOrders FROM customers c HAVING TotalOrders >= 3 ORDER BY TotalOrders DESC;",
   "Four-table join customers-orders-order details-products. A single order with several Beverages lines would be counted once per line, so COUNT(DISTINCT o.`Order ID`) counts orders, not lines. The category filter goes in WHERE (row filter) and the >= 3 test in HAVING (group filter). The date range uses >= and < instead of YEAR() so an index on Order Date stays usable. In this dump no customer has 3 such orders (max is 2), so the result is empty; lower the threshold to see rows.",
   'multi_agg', 'beverages orders per customer|count distinct|having|year range|four table join', 'join with COUNT DISTINCT + HAVING|correlated count with EXISTS', 'ordered'),
 S(31, "Find customers who placed at least 2 distinct orders containing products in the 'Beverages' category during 2006. Return customer ID, First Name, Last Name, and TotalOrders. Sort by TotalOrders in descending order.",
   "SELECT c.ID, c.`First Name`, c.`Last Name`, COUNT(DISTINCT o.`Order ID`) AS TotalOrders FROM customers c JOIN orders o ON o.`Customer ID`=c.ID JOIN `order details` d ON d.`Order ID`=o.`Order ID` JOIN products p ON p.ID=d.`Product ID` WHERE p.Category='Beverages' AND o.`Order Date` >= '2006-01-01' AND o.`Order Date` < '2007-01-01' GROUP BY c.ID, c.`First Name`, c.`Last Name` HAVING COUNT(DISTINCT o.`Order ID`) >= 2 ORDER BY TotalOrders DESC, c.ID;",
   "SELECT c.ID, c.`First Name`, c.`Last Name`, (SELECT COUNT(*) FROM orders o WHERE o.`Customer ID`=c.ID AND o.`Order Date` >= '2006-01-01' AND o.`Order Date` < '2007-01-01' AND EXISTS (SELECT 1 FROM `order details` d JOIN products p ON p.ID=d.`Product ID` WHERE d.`Order ID`=o.`Order ID` AND p.Category='Beverages')) AS TotalOrders FROM customers c HAVING TotalOrders >= 2 ORDER BY TotalOrders DESC, c.ID;",
   'Same shape as SQL5-030 with a different threshold or category. Threshold 2 returns one customer in this dump (2 Beverages orders), so the result is non-empty. COUNT(DISTINCT o.`Order ID`) counts orders, not lines; the category test is a row filter in WHERE and the order-count test a group filter in HAVING. `, c.ID` is added to ORDER BY so tied counts come back in a fixed order.',
   'multi_agg', 'orders per customer by category|count distinct|having|year range|four table join', 'join with COUNT DISTINCT + HAVING|correlated count with EXISTS', 'ordered'),
 S(32, "Find customers who placed at least 1 distinct orders containing products in the 'Beverages' category during 2006. Return customer ID, First Name, Last Name, and TotalOrders. Sort by TotalOrders in descending order.",
   "SELECT c.ID, c.`First Name`, c.`Last Name`, COUNT(DISTINCT o.`Order ID`) AS TotalOrders FROM customers c JOIN orders o ON o.`Customer ID`=c.ID JOIN `order details` d ON d.`Order ID`=o.`Order ID` JOIN products p ON p.ID=d.`Product ID` WHERE p.Category='Beverages' AND o.`Order Date` >= '2006-01-01' AND o.`Order Date` < '2007-01-01' GROUP BY c.ID, c.`First Name`, c.`Last Name` HAVING COUNT(DISTINCT o.`Order ID`) >= 1 ORDER BY TotalOrders DESC, c.ID;",
   "SELECT c.ID, c.`First Name`, c.`Last Name`, (SELECT COUNT(*) FROM orders o WHERE o.`Customer ID`=c.ID AND o.`Order Date` >= '2006-01-01' AND o.`Order Date` < '2007-01-01' AND EXISTS (SELECT 1 FROM `order details` d JOIN products p ON p.ID=d.`Product ID` WHERE d.`Order ID`=o.`Order ID` AND p.Category='Beverages')) AS TotalOrders FROM customers c HAVING TotalOrders >= 1 ORDER BY TotalOrders DESC, c.ID;",
   'Same shape as SQL5-030 with a different threshold or category. Threshold 1 is the sanity check for SQL5-030: ten customers in this dump, so the join and date filter are exercised. COUNT(DISTINCT o.`Order ID`) counts orders, not lines; the category test is a row filter in WHERE and the order-count test a group filter in HAVING. `, c.ID` is added to ORDER BY so tied counts come back in a fixed order.',
   'multi_agg', 'orders per customer by category|count distinct|having|year range|four table join', 'join with COUNT DISTINCT + HAVING|correlated count with EXISTS', 'ordered'),
 S(33, "Find customers who placed at least 2 distinct orders containing products in the 'Dried Fruit & Nuts' category during 2006. Return customer ID, First Name, Last Name, and TotalOrders. Sort by TotalOrders in descending order.",
   "SELECT c.ID, c.`First Name`, c.`Last Name`, COUNT(DISTINCT o.`Order ID`) AS TotalOrders FROM customers c JOIN orders o ON o.`Customer ID`=c.ID JOIN `order details` d ON d.`Order ID`=o.`Order ID` JOIN products p ON p.ID=d.`Product ID` WHERE p.Category='Dried Fruit & Nuts' AND o.`Order Date` >= '2006-01-01' AND o.`Order Date` < '2007-01-01' GROUP BY c.ID, c.`First Name`, c.`Last Name` HAVING COUNT(DISTINCT o.`Order ID`) >= 2 ORDER BY TotalOrders DESC, c.ID;",
   "SELECT c.ID, c.`First Name`, c.`Last Name`, (SELECT COUNT(*) FROM orders o WHERE o.`Customer ID`=c.ID AND o.`Order Date` >= '2006-01-01' AND o.`Order Date` < '2007-01-01' AND EXISTS (SELECT 1 FROM `order details` d JOIN products p ON p.ID=d.`Product ID` WHERE d.`Order ID`=o.`Order ID` AND p.Category='Dried Fruit & Nuts')) AS TotalOrders FROM customers c HAVING TotalOrders >= 2 ORDER BY TotalOrders DESC, c.ID;",
   'Same shape as SQL5-030 with a different threshold or category. Only the category literal changes; Dried Fruit & Nuts has one customer with 2 orders in 2006. COUNT(DISTINCT o.`Order ID`) counts orders, not lines; the category test is a row filter in WHERE and the order-count test a group filter in HAVING. `, c.ID` is added to ORDER BY so tied counts come back in a fixed order.',
   'multi_agg', 'orders per customer by category|count distinct|having|year range|four table join', 'join with COUNT DISTINCT + HAVING|correlated count with EXISTS', 'ordered'),
 S(34, "For each product category, consider only products with List Price at least 20. Display Category, the number of qualifying products as TotalProducts, the sum of their List Prices as TotalListPrice, and their average List Price as AverageListPrice rounded to 2 decimal places. Include only categories with TotalListPrice greater than 100. Sort by TotalListPrice in descending order.",
   "SELECT Category, COUNT(*) AS TotalProducts, SUM(`List Price`) AS TotalListPrice, ROUND(AVG(`List Price`), 2) AS AverageListPrice FROM products WHERE `List Price` >= 20 GROUP BY Category HAVING SUM(`List Price`) > 100 ORDER BY TotalListPrice DESC;",
   "SELECT Category, TotalProducts, TotalListPrice, ROUND(TotalListPrice / TotalProducts, 2) AS AverageListPrice FROM (SELECT Category, COUNT(*) AS TotalProducts, SUM(`List Price`) AS TotalListPrice FROM products WHERE `List Price` >= 20 GROUP BY Category) t WHERE TotalListPrice > 100 ORDER BY TotalListPrice DESC;",
   "The price condition on single rows belongs in WHERE (before grouping) and the condition on the group total belongs in HAVING (after grouping); swapping them changes the answer. The alias TotalListPrice may be used in ORDER BY but not in HAVING of the same query in standard SQL, so HAVING repeats SUM. The alternative computes the average as sum divided by count in an outer query. Two categories qualify in this dump (Dried Fruit & Nuts 106.25, Jams, Preserves 106.00).",
   'group_having', 'category price filter|where vs having|sum having|round average', 'WHERE then HAVING on SUM|derived table then outer filter', 'ordered'),
 S(35, "For each product category, consider only products with List Price below 20. Display Category, TotalProducts, TotalListPrice and AverageListPrice rounded to 2 decimal places. Include only categories with at least 3 qualifying products. Sort by AverageListPrice in ascending order, then by Category alphabetically.",
   "SELECT Category, COUNT(*) AS TotalProducts, SUM(`List Price`) AS TotalListPrice, ROUND(AVG(`List Price`), 2) AS AverageListPrice FROM products WHERE `List Price` < 20 GROUP BY Category HAVING COUNT(*) >= 3 ORDER BY AverageListPrice, Category;",
   "SELECT Category, TotalProducts, TotalListPrice, ROUND(TotalListPrice / TotalProducts, 2) AS AverageListPrice FROM (SELECT Category, COUNT(*) AS TotalProducts, SUM(`List Price`) AS TotalListPrice FROM products WHERE `List Price` < 20 GROUP BY Category) t WHERE TotalProducts >= 3 ORDER BY AverageListPrice, Category;",
   "Same shape as SQL5-034 with the opposite price bound and a count threshold instead of a sum threshold. Products with NULL List Price fail the < 20 test and are dropped by WHERE. Category is added as the last sort key so equal averages come back in a fixed order.",
   'group_having', 'category price filter|below threshold|count having|round average', 'WHERE then HAVING on COUNT|derived table then outer filter', 'ordered'),
 S(36, "Display products with List Price between 20 and 50, inclusive. Return ID, Product Name, List Price, and the price after a 15% increase as NewPrice, rounded to 2 decimal places. Sort by NewPrice in descending order, then by ID in ascending order.",
   "SELECT ID, `Product Name`, `List Price`, ROUND(`List Price` * 1.15, 2) AS NewPrice FROM products WHERE `List Price` BETWEEN 20 AND 50 ORDER BY NewPrice DESC, ID;",
   "SELECT ID, `Product Name`, `List Price`, NewPrice FROM (SELECT ID, `Product Name`, `List Price`, ROUND(`List Price` + `List Price` * 0.15, 2) AS NewPrice FROM products) t WHERE `List Price` >= 20 AND `List Price` <= 50 ORDER BY NewPrice DESC, ID;",
   "BETWEEN is inclusive on both ends, so it equals >= 20 AND <= 50. A 15% increase is multiplying by 1.15 (not 0.15). ROUND(x, 2) is applied in the SELECT list; ORDER BY NewPrice then sorts by the rounded value, and the ID key makes ties deterministic. The dump has no product at exactly 20 or 50, so the boundary is not tested by the data.",
   'computed', 'between inclusive|percentage increase|round|order by alias', 'BETWEEN with ROUND(x*1.15)|explicit >= and <= with x + x*0.15', 'ordered'),
 S(37, "Display products with List Price between 10 and 30, inclusive. Return ID, Product Name, List Price, and the price after a 20% increase as NewPrice, rounded to 2 decimal places. Sort by NewPrice in ascending order, then by ID in ascending order.",
   "SELECT ID, `Product Name`, `List Price`, ROUND(`List Price` * 1.20, 2) AS NewPrice FROM products WHERE `List Price` BETWEEN 10 AND 30 ORDER BY NewPrice, ID;",
   "SELECT ID, `Product Name`, `List Price`, NewPrice FROM (SELECT ID, `Product Name`, `List Price`, ROUND(`List Price` + `List Price` * 0.20, 2) AS NewPrice FROM products) t WHERE `List Price` >= 10 AND `List Price` <= 30 ORDER BY NewPrice, ID;",
   "Variant of SQL5-036 with another range, another percentage and ascending order. Here the dump has a product at exactly 10.00 and one at exactly 30.00, so the inclusive boundary matters and a strict < would drop them.",
   'computed', 'between inclusive|percentage increase|round|boundary', 'BETWEEN with ROUND(x*1.2)|explicit >= and <= with x + x*0.2', 'ordered'),
 S(38, "Apply a 10% discount to each product. Return ID, Product Name, List Price, DiscountAmount, and DiscountedPrice. Include only products with DiscountedPrice at least 30. Round both calculated amounts to 2 decimal places for display, but use the unrounded DiscountedPrice for filtering. Sort by DiscountedPrice in ascending order.",
   "SELECT ID, `Product Name`, `List Price`, ROUND(`List Price` * 0.10, 2) AS DiscountAmount, ROUND(`List Price` * 0.90, 2) AS DiscountedPrice FROM products WHERE `List Price` * 0.90 >= 30 ORDER BY `List Price` * 0.90, ID;",
   "SELECT ID, `Product Name`, `List Price`, ROUND(`List Price` - raw, 2) AS DiscountAmount, ROUND(raw, 2) AS DiscountedPrice FROM (SELECT ID, `Product Name`, `List Price`, `List Price` - `List Price` * 0.10 AS raw FROM products) t WHERE raw >= 30 ORDER BY raw, ID;",
   "WHERE is evaluated before SELECT, so it must repeat the unrounded expression (aliases are not visible there, and the question forbids filtering on the rounded value: a price of 33.33 gives 29.997, which rounds to 30.00 but is below 30). ORDER BY also uses the unrounded expression because the alias DiscountedPrice would be the rounded one. ID breaks ties between equal prices. The dump has no product near the 33.33 boundary, so both ways give the same rows here.",
   'computed', 'discount|round only for display|filter on unrounded|where cannot use alias', 'filter on unrounded expression|price minus discount form', 'ordered'),
 S(39, "Apply a 25% discount to each product. Return ID, Product Name, List Price, DiscountAmount, and DiscountedPrice. Include only products with DiscountedPrice at least 15. Round both calculated amounts to 2 decimal places for display, but use the unrounded DiscountedPrice for filtering. Sort by DiscountedPrice in descending order, then by ID in ascending order.",
   "SELECT ID, `Product Name`, `List Price`, ROUND(`List Price` * 0.25, 2) AS DiscountAmount, ROUND(`List Price` * 0.75, 2) AS DiscountedPrice FROM products WHERE `List Price` * 0.75 >= 15 ORDER BY `List Price` * 0.75 DESC, ID;",
   "SELECT ID, `Product Name`, `List Price`, ROUND(`List Price` - raw, 2) AS DiscountAmount, ROUND(raw, 2) AS DiscountedPrice FROM (SELECT ID, `Product Name`, `List Price`, `List Price` - `List Price` * 0.25 AS raw FROM products) t WHERE raw >= 15 ORDER BY raw DESC, ID;",
   "Variant of SQL5-038 with another rate, another threshold and descending order. A 25% discount multiplies by 0.75; a List Price of exactly 20 would give 15.00, so >= (not >) matters at the boundary, although the dump has no product at 20.",
   'computed', 'discount|round only for display|filter on unrounded|descending sort', 'filter on unrounded expression|price minus discount form', 'ordered'),
 S(40, "Count orders placed in each month of 2006. Return the year and month in YYYY-MM format as OrderMonth, and the number of orders as TotalOrders. Include only months with at least 5 orders. Sort chronologically by OrderMonth. Months with no orders do not need to appear.",
   "SELECT DATE_FORMAT(`Order Date`, '%Y-%m') AS OrderMonth, COUNT(*) AS TotalOrders FROM orders WHERE `Order Date` >= '2006-01-01' AND `Order Date` < '2007-01-01' GROUP BY DATE_FORMAT(`Order Date`, '%Y-%m') HAVING COUNT(*) >= 5 ORDER BY OrderMonth;",
   "SELECT CONCAT(y, '-', LPAD(m, 2, '0')) AS OrderMonth, TotalOrders FROM (SELECT YEAR(`Order Date`) AS y, MONTH(`Order Date`) AS m, COUNT(*) AS TotalOrders FROM orders WHERE `Order Date` >= '2006-01-01' AND `Order Date` < '2007-01-01' GROUP BY YEAR(`Order Date`), MONTH(`Order Date`)) t WHERE TotalOrders >= 5 ORDER BY y, m;",
   "DATE_FORMAT with '%Y-%m' builds the group key as text; because the format is year first with a zero-padded month, sorting the text is also chronological order. The year filter uses a half-open date range so an index on Order Date stays usable (YEAR() on the column would not). The alternative groups by numeric year and month and pads the month with LPAD. Four months qualify in this dump (March to June); January (4) and February (3) are dropped by HAVING.",
   'date', 'orders per month|date format|year month|having count', 'DATE_FORMAT group key|YEAR and MONTH with LPAD', 'ordered'),
 S(41, "Count orders placed in each month of 2006. Return the year and month in YYYY-MM format as OrderMonth, and the number of orders as TotalOrders. Include only months with fewer than 5 orders. Sort chronologically by OrderMonth.",
   "SELECT DATE_FORMAT(`Order Date`, '%Y-%m') AS OrderMonth, COUNT(*) AS TotalOrders FROM orders WHERE `Order Date` >= '2006-01-01' AND `Order Date` < '2007-01-01' GROUP BY DATE_FORMAT(`Order Date`, '%Y-%m') HAVING COUNT(*) < 5 ORDER BY OrderMonth;",
   "SELECT CONCAT(y, '-', LPAD(m, 2, '0')) AS OrderMonth, TotalOrders FROM (SELECT YEAR(`Order Date`) AS y, MONTH(`Order Date`) AS m, COUNT(*) AS TotalOrders FROM orders WHERE `Order Date` >= '2006-01-01' AND `Order Date` < '2007-01-01' GROUP BY YEAR(`Order Date`), MONTH(`Order Date`)) t WHERE TotalOrders < 5 ORDER BY y, m;",
   "Same as SQL5-040 with the HAVING direction reversed (fewer than 5). Months with zero orders still do not appear, because GROUP BY only creates groups for rows that exist; listing empty months would need a calendar table with LEFT JOIN. January (4) and February (3) qualify in this dump.",
   'date', 'orders per month|date format|having less than|year month', 'DATE_FORMAT group key|YEAR and MONTH with LPAD', 'ordered'),
 S(42, "Count orders placed in each quarter of 2006. Return the quarter as OrderQuarter in YYYY-Qn format (for example 2006-Q1) and the number of orders as TotalOrders. Include only quarters with at least 20 orders. Sort chronologically.",
   "SELECT CONCAT(YEAR(`Order Date`), '-Q', QUARTER(`Order Date`)) AS OrderQuarter, COUNT(*) AS TotalOrders FROM orders WHERE `Order Date` >= '2006-01-01' AND `Order Date` < '2007-01-01' GROUP BY OrderQuarter HAVING COUNT(*) >= 20 ORDER BY OrderQuarter;",
   "SELECT CONCAT(y, '-Q', q) AS OrderQuarter, SUM(TotalOrders) AS TotalOrders FROM (SELECT YEAR(`Order Date`) AS y, CEIL(MONTH(`Order Date`) / 3) AS q, COUNT(*) AS TotalOrders FROM orders WHERE `Order Date` >= '2006-01-01' AND `Order Date` < '2007-01-01' GROUP BY YEAR(`Order Date`), MONTH(`Order Date`), CEIL(MONTH(`Order Date`) / 3)) t GROUP BY y, q HAVING SUM(TotalOrders) >= 20 ORDER BY y, q;",
   "QUARTER() returns 1 to 4; there is no DATE_FORMAT code for quarter, so the label is built with CONCAT. The alternative first counts per month and then groups months into quarters with CEIL(month / 3), summing the monthly counts. Only Q2 reaches 20 orders in this dump (Q1 has 15, Q2 has 33); the sum in the alternative must be SUM(TotalOrders), not COUNT.",
   'date', 'orders per quarter|quarter function|date label|having count', 'QUARTER with CONCAT|month counts rolled up with CEIL', 'ordered'),
 S(43, "Display all products with ID, Product Name, List Price, and PriceLevel. Assign 'Unknown' when List Price is NULL, 'Low' when it is below 20, 'Medium' when it is at least 20 but below 50, and 'High' when it is at least 50. Sort by ID in ascending order.",
   "SELECT ID, `Product Name`, `List Price`, CASE WHEN `List Price` IS NULL THEN 'Unknown' WHEN `List Price` < 20 THEN 'Low' WHEN `List Price` < 50 THEN 'Medium' ELSE 'High' END AS PriceLevel FROM products ORDER BY ID;",
   "SELECT ID, `Product Name`, `List Price`, IF(`List Price` IS NULL, 'Unknown', IF(`List Price` < 20, 'Low', IF(`List Price` < 50, 'Medium', 'High'))) AS PriceLevel FROM products ORDER BY ID;",
   "CASE checks branches top to bottom and stops at the first match, so the NULL test must come first: NULL < 20 is unknown, and a NULL would otherwise fall to ELSE and be labelled High. Because the order guarantees the lower bound, 'Medium' needs only < 50 and ELSE covers the rest. Nested IF is the MySQL-only equivalent. No product has a NULL List Price in this dump, so the 'Unknown' branch is never used here.",
   'cond_agg', 'case when|price level|null first|bucket', 'searched CASE with NULL branch first|nested IF', 'ordered'),
 S(44, "Count how many products fall into each price level: 'Unknown' when List Price is NULL, 'Low' below 20, 'Medium' from 20 up to below 50, and 'High' at 50 or more. Return PriceLevel and TotalProducts; levels with no products do not need to appear.",
   "SELECT CASE WHEN `List Price` IS NULL THEN 'Unknown' WHEN `List Price` < 20 THEN 'Low' WHEN `List Price` < 50 THEN 'Medium' ELSE 'High' END AS PriceLevel, COUNT(*) AS TotalProducts FROM products GROUP BY PriceLevel;",
   "SELECT lvl AS PriceLevel, COUNT(*) AS TotalProducts FROM (SELECT IF(`List Price` IS NULL, 'Unknown', IF(`List Price` < 20, 'Low', IF(`List Price` < 50, 'Medium', 'High'))) AS lvl FROM products) t GROUP BY lvl;",
   "Grouping by a CASE expression: MySQL lets GROUP BY use the SELECT alias. COUNT(*) is correct here because every row falls in exactly one level, including the NULL ones. Levels without products are simply absent; use a lookup or UNION of all four labels with LEFT JOIN to show zeros.",
   'cond_agg', 'case when|group by case|price level|bucket count', 'GROUP BY CASE alias|derived table then GROUP BY', 'set'),
 S(45, "For each product category, return Category, TotalProducts, LowPriceProducts, and HighPriceProducts. LowPriceProducts counts products with List Price below 20. HighPriceProducts counts products with List Price at least 20. Products with NULL List Price must be included in TotalProducts but excluded from both price counts. Sort by Category alphabetically.",
   "SELECT Category, COUNT(*) AS TotalProducts, COUNT(CASE WHEN `List Price` < 20 THEN 1 END) AS LowPriceProducts, COUNT(CASE WHEN `List Price` >= 20 THEN 1 END) AS HighPriceProducts FROM products GROUP BY Category ORDER BY Category;",
   "SELECT Category, COUNT(*) AS TotalProducts, SUM(IF(`List Price` < 20, 1, 0)) AS LowPriceProducts, SUM(IF(`List Price` >= 20, 1, 0)) AS HighPriceProducts FROM products GROUP BY Category ORDER BY Category;",
   "Conditional aggregation: COUNT ignores NULL, so COUNT(CASE WHEN cond THEN 1 END) counts only rows where the condition is true. For a NULL List Price both conditions are unknown, the CASE yields NULL (no ELSE), and the row is counted by COUNT(*) only, as the question requires. SUM(IF(cond, 1, 0)) is equivalent because IF treats an unknown condition as false. No product has a NULL List Price in this dump, so the NULL rule cannot be observed in the data.",
   'cond_agg', 'conditional aggregation|count case|null excluded|price buckets per category', 'COUNT(CASE WHEN)|SUM(IF)', 'ordered'),
 S(46, "Find categories that contain at least one product with List Price below 20 and at least one product with List Price at least 20. Return Category. Sort alphabetically.",
   "SELECT Category FROM products GROUP BY Category HAVING COUNT(CASE WHEN `List Price` < 20 THEN 1 END) > 0 AND COUNT(CASE WHEN `List Price` >= 20 THEN 1 END) > 0 ORDER BY Category;",
   "SELECT DISTINCT p.Category FROM products p WHERE p.`List Price` < 20 AND EXISTS (SELECT 1 FROM products q WHERE q.Category = p.Category AND q.`List Price` >= 20) ORDER BY p.Category;",
   "Both conditions must hold inside one group, so each is a conditional count in HAVING. A WHERE clause cannot express it, because a single row cannot be both below and above 20. The alternative finds a low product and checks with EXISTS that its category also has a high one; DISTINCT removes repeated categories.",
   'cond_agg', 'conditional having|both low and high|exists same category|group condition', 'HAVING with two conditional counts|EXISTS on same category', 'ordered'),
 S(47, "Find products whose Product Name contains the word fragment 'tea' but does not contain 'green'. Return ID, Product Name, Category, and List Price. Include only products with List Price greater than 10. Sort by Product Name alphabetically. Use LIKE with the database's existing collation.",
   "SELECT ID, `Product Name`, Category, `List Price` FROM products WHERE `Product Name` LIKE '%tea%' AND `Product Name` NOT LIKE '%green%' AND `List Price` > 10 ORDER BY `Product Name`;",
   "SELECT ID, `Product Name`, Category, `List Price` FROM products WHERE ID IN (SELECT ID FROM products WHERE LOCATE('tea', LOWER(`Product Name`)) > 0) AND ID NOT IN (SELECT ID FROM products WHERE LOCATE('green', LOWER(`Product Name`)) > 0) AND `List Price` > 10 ORDER BY `Product Name`;",
   "LIKE '%tea%' matches the fragment anywhere in the name; NOT LIKE excludes the other word. Case-insensitivity comes from the column collation (_ci), which is what the question asks to rely on; LOWER plus LOCATE is the explicit equivalent. EMPTY RESULT in this dump: the only names with 'tea' are 'Northwind Traders Green Tea' (excluded by green, price 2.99) and 'Northwind Traders Tea' (price 4.00, not above 10), so the query is a pattern reference. See SQL5-049 for a threshold that returns a row.",
   'string_funcs', 'like contains|not like|word fragment|collation|price filter', 'LIKE and NOT LIKE|IN and NOT IN subqueries', 'ordered'),
 S(48, "Find products whose Product Name contains the word fragment 'sauce' but does not contain 'hot'. Return ID, Product Name, Category, and List Price. Include only products with List Price greater than 10. Sort by Product Name alphabetically. Use LIKE with the database's existing collation.",
   "SELECT ID, `Product Name`, Category, `List Price` FROM products WHERE `Product Name` LIKE '%sauce%' AND `Product Name` NOT LIKE '%hot%' AND `List Price` > 10 ORDER BY `Product Name`;",
   "SELECT ID, `Product Name`, Category, `List Price` FROM products WHERE ID IN (SELECT ID FROM products WHERE LOCATE('sauce', LOWER(`Product Name`)) > 0) AND ID NOT IN (SELECT ID FROM products WHERE LOCATE('hot', LOWER(`Product Name`)) > 0) AND `List Price` > 10 ORDER BY `Product Name`;",
   "Same shape as SQL5-047 with other words, so the result is not empty. A short fragment such as 'hot' can occur inside longer words (for example 'shot'), which NOT LIKE '%hot%' would also exclude; match on word boundaries with REGEXP '\\\\bhot\\\\b' if that matters.",
   'string_funcs', 'like contains|not like|word fragment|price filter', 'LIKE and NOT LIKE|LOCATE inside IN / NOT IN subqueries', 'ordered'),
 S(49, "Find products whose Product Name contains the word fragment 'tea' but does not contain 'green'. Return ID, Product Name, Category, and List Price. Include only products with List Price greater than 3. Sort by Product Name alphabetically.",
   "SELECT ID, `Product Name`, Category, `List Price` FROM products WHERE `Product Name` LIKE '%tea%' AND `Product Name` NOT LIKE '%green%' AND `List Price` > 3 ORDER BY `Product Name`;",
   "SELECT ID, `Product Name`, Category, `List Price` FROM products WHERE ID IN (SELECT ID FROM products WHERE LOCATE('tea', LOWER(`Product Name`)) > 0) AND ID NOT IN (SELECT ID FROM products WHERE LOCATE('green', LOWER(`Product Name`)) > 0) AND `List Price` > 3 ORDER BY `Product Name`;",
   "Threshold variant of SQL5-047: lowering the price bound to 3 returns 'Northwind Traders Tea' (4.00), which shows the text filters are correct while the original threshold leaves the result empty.",
   'string_funcs', 'like contains|not like|threshold variant|price filter', 'LIKE and NOT LIKE|LOCATE inside IN / NOT IN subqueries', 'ordered'),
 S(50, "List the sixth through tenth most expensive products with non-NULL List Price. Return ID, Product Name, and List Price. Rank products by List Price in descending order, breaking price ties by ID in ascending order. Return at most 5 rows.",
   "SELECT ID, `Product Name`, `List Price` FROM products WHERE `List Price` IS NOT NULL ORDER BY `List Price` DESC, ID LIMIT 5 OFFSET 5;",
   "SELECT ID, `Product Name`, `List Price` FROM (SELECT ID, `Product Name`, `List Price`, ROW_NUMBER() OVER (ORDER BY `List Price` DESC, ID) AS rn FROM products WHERE `List Price` IS NOT NULL) t WHERE rn BETWEEN 6 AND 10 ORDER BY rn;",
   "OFFSET 5 skips the five most expensive rows (it does not delete them) and LIMIT 5 takes the next five. The ID key makes the order total, so the page boundary is deterministic when prices tie. In descending order NULLs sort last in MySQL, but the explicit IS NOT NULL also keeps them out of the ranking. ROW_NUMBER numbers rows 1, 2, 3 without ties, so rn BETWEEN 6 AND 10 is the same window (MySQL 8.0 window function).",
   'topn_rank', 'pagination|offset|sixth to tenth|row number|tie break', 'LIMIT with OFFSET|ROW_NUMBER range', 'ordered'),
 S(51, "List the third through fifth cheapest products with non-NULL List Price. Return ID, Product Name, and List Price. Rank products by List Price in ascending order, breaking price ties by ID in ascending order. Return at most 3 rows.",
   "SELECT ID, `Product Name`, `List Price` FROM products WHERE `List Price` IS NOT NULL ORDER BY `List Price`, ID LIMIT 3 OFFSET 2;",
   "SELECT ID, `Product Name`, `List Price` FROM (SELECT ID, `Product Name`, `List Price`, ROW_NUMBER() OVER (ORDER BY `List Price`, ID) AS rn FROM products WHERE `List Price` IS NOT NULL) t WHERE rn BETWEEN 3 AND 5 ORDER BY rn;",
   "Variant of SQL5-050: cheapest instead of most expensive, so the sort is ascending; OFFSET is first rank minus one (3 - 1 = 2) and LIMIT is the size of the window (5 - 3 + 1 = 3). Without IS NOT NULL a NULL price would sort first in ascending order and take the first rank.",
   'topn_rank', 'pagination|offset|third to fifth|cheapest|tie break', 'LIMIT with OFFSET|ROW_NUMBER range', 'ordered'),
 S(52, "Find all products whose List Price is one of the sixth through tenth highest distinct List Price values. Return ID, Product Name, and List Price. Products sharing a price all appear. Sort by List Price in descending order, then by ID in ascending order.",
   "SELECT ID, `Product Name`, `List Price` FROM (SELECT ID, `Product Name`, `List Price`, DENSE_RANK() OVER (ORDER BY `List Price` DESC) AS dr FROM products WHERE `List Price` IS NOT NULL) t WHERE dr BETWEEN 6 AND 10 ORDER BY `List Price` DESC, ID;",
   "SELECT p.ID, p.`Product Name`, p.`List Price` FROM products p JOIN (SELECT DISTINCT `List Price` AS price FROM products WHERE `List Price` IS NOT NULL ORDER BY price DESC LIMIT 5 OFFSET 5) x ON x.price = p.`List Price` ORDER BY p.`List Price` DESC, p.ID;",
   "DENSE_RANK gives equal prices the same rank with no gaps, so ranks 6 to 10 are the sixth to tenth distinct prices and every product at those prices is kept; ROW_NUMBER or LIMIT on rows would cut ties arbitrarily. The alternative picks the distinct prices with LIMIT/OFFSET in a derived table (MySQL does not allow LIMIT inside IN) and joins back.",
   'topn_rank', 'dense rank|distinct price levels|ties included|sixth to tenth', 'DENSE_RANK window|derived distinct prices with LIMIT OFFSET', 'ordered'),
 S(53, "Find categories whose number of products is greater than the average number of products per category. Exclude products with Category NULL from all calculations. Return Category and TotalProducts. Sort by TotalProducts in descending order, then by Category alphabetically.",
   "SELECT Category, COUNT(*) AS TotalProducts FROM products WHERE Category IS NOT NULL GROUP BY Category HAVING COUNT(*) > (SELECT AVG(cnt) FROM (SELECT COUNT(*) AS cnt FROM products WHERE Category IS NOT NULL GROUP BY Category) t) ORDER BY TotalProducts DESC, Category;",
   "SELECT Category, COUNT(*) AS TotalProducts FROM products WHERE Category IS NOT NULL GROUP BY Category HAVING COUNT(*) > (SELECT COUNT(*) / COUNT(DISTINCT Category) FROM products WHERE Category IS NOT NULL) ORDER BY TotalProducts DESC, Category;",
   "The average is of per-category counts, so it needs two levels: count per category, then AVG of those counts. Averaging products directly would be wrong. Because the average equals total products divided by number of categories, the alternative computes it in one pass. The NULL exclusion must be repeated in the inner and the outer query, otherwise NULL becomes a group of its own. In this dump the average is 45 / 16 = 2.8125, so categories with 3 or more products qualify.",
   'group_having', 'above average count|average of counts|having subquery|exclude null category', 'HAVING with AVG over grouped derived table|total divided by distinct count', 'ordered'),
 S(54, "Find categories whose number of products is smaller than the average number of products per category. Exclude products with Category NULL from all calculations. Return Category and TotalProducts. Sort by TotalProducts in ascending order, then by Category alphabetically.",
   "SELECT Category, COUNT(*) AS TotalProducts FROM products WHERE Category IS NOT NULL GROUP BY Category HAVING COUNT(*) < (SELECT AVG(cnt) FROM (SELECT COUNT(*) AS cnt FROM products WHERE Category IS NOT NULL GROUP BY Category) t) ORDER BY TotalProducts, Category;",
   "SELECT Category, COUNT(*) AS TotalProducts FROM products WHERE Category IS NOT NULL GROUP BY Category HAVING COUNT(*) < (SELECT COUNT(*) / COUNT(DISTINCT Category) FROM products WHERE Category IS NOT NULL) ORDER BY TotalProducts, Category;",
   "Variant of SQL5-053 with the opposite comparison and sort. A category exactly at the average would appear in neither list; with an average of 2.8125 no category does.",
   'group_having', 'below average count|average of counts|having subquery|exclude null category', 'HAVING with AVG over grouped derived table|total divided by distinct count', 'ordered'),
 S(55, "Find categories whose average List Price is greater than the average List Price of all products with a non-NULL Category. Return Category and AveragePrice rounded to 2 decimal places. Sort by AveragePrice in descending order, then by Category alphabetically.",
   "SELECT Category, ROUND(AVG(`List Price`), 2) AS AveragePrice FROM products WHERE Category IS NOT NULL GROUP BY Category HAVING AVG(`List Price`) > (SELECT AVG(`List Price`) FROM products WHERE Category IS NOT NULL) ORDER BY AveragePrice DESC, Category;",
   "SELECT c.Category, ROUND(c.avg_price, 2) AS AveragePrice FROM (SELECT Category, AVG(`List Price`) AS avg_price FROM products WHERE Category IS NOT NULL GROUP BY Category) c CROSS JOIN (SELECT AVG(`List Price`) AS overall FROM products WHERE Category IS NOT NULL) o WHERE c.avg_price > o.overall ORDER BY AveragePrice DESC, c.Category;",
   "Compare each group aggregate with a whole-table aggregate: the group value in HAVING and a scalar subquery on the right. The comparison uses the unrounded averages; only the displayed value is rounded. AVG skips NULL prices, so the overall average is over priced products only. The alternative joins a one-row table of the overall average with CROSS JOIN.",
   'group_having', 'category above overall average|having scalar subquery|average price|cross join one row', 'HAVING vs scalar subquery|CROSS JOIN with overall average', 'ordered'),
 S(56, "For each non-NULL product category, return Category, TotalProducts, and ProductPercentage. ProductPercentage is the number of products in the category divided by the total number of products with non-NULL Category, multiplied by 100 and rounded to 2 decimal places. Sort by ProductPercentage in descending order, then by Category alphabetically.",
   "SELECT Category, COUNT(*) AS TotalProducts, ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM products WHERE Category IS NOT NULL), 2) AS ProductPercentage FROM products WHERE Category IS NOT NULL GROUP BY Category ORDER BY ProductPercentage DESC, Category;",
   "SELECT Category, COUNT(*) AS TotalProducts, ROUND(100 * COUNT(*) / SUM(COUNT(*)) OVER (), 2) AS ProductPercentage FROM products WHERE Category IS NOT NULL GROUP BY Category ORDER BY ProductPercentage DESC, Category;",
   "Percent of total: the denominator is the total over all non-NULL categories, from a scalar subquery or from SUM(COUNT(*)) OVER () (a window function applied after grouping, MySQL 8.0). Multiply by 100.0 before dividing so integer division cannot give 0. The WHERE filter must be in both the group query and the denominator. The ORDER BY alias is the rounded value; categories with equal counts tie and are ordered by Category.",
   'multi_agg', 'percentage of total|window over groups|scalar subquery denominator|round', 'scalar subquery denominator|SUM(COUNT(*)) OVER ()', 'ordered'),
 S(57, "For each non-NULL product category, return Category, TotalListPrice, and PricePercentage. PricePercentage is the category's sum of List Price divided by the sum of List Price over all products with non-NULL Category, multiplied by 100 and rounded to 2 decimal places. Sort by PricePercentage in descending order, then by Category alphabetically.",
   "SELECT Category, SUM(`List Price`) AS TotalListPrice, ROUND(SUM(`List Price`) * 100.0 / (SELECT SUM(`List Price`) FROM products WHERE Category IS NOT NULL), 2) AS PricePercentage FROM products WHERE Category IS NOT NULL GROUP BY Category ORDER BY PricePercentage DESC, Category;",
   "SELECT Category, SUM(`List Price`) AS TotalListPrice, ROUND(100 * SUM(`List Price`) / SUM(SUM(`List Price`)) OVER (), 2) AS PricePercentage FROM products WHERE Category IS NOT NULL GROUP BY Category ORDER BY PricePercentage DESC, Category;",
   "Variant of SQL5-056: share of a sum instead of a count. The shape is identical (group total over grand total); only the aggregate changes from COUNT(*) to SUM(List Price). The shares add up to about 100, with small rounding differences.",
   'multi_agg', 'percentage of total|sum share|window over groups|scalar subquery denominator', 'scalar subquery denominator|SUM(SUM()) OVER ()', 'ordered'),
]
